async function sustained(){const start=performance.now(),limit=12000,maxBytes=20*1024*1024,chunk=2*1024*1024;let bytes=0,runs=0,errors=[];while(performance.now()-start<limit&&bytes<maxBytes){try{const r=await fetch('https://speed.cloudflare.com/__down?bytes='+chunk+'&s='+Date.now()+'-'+runs,{cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('HTTP '+r.status);const b=await r.arrayBuffer();bytes+=b.byteLength;runs++;}catch(e){errors.push(e.message);break;}}const sec=(performance.now()-start)/1000,mbps=sec?bytes*8/sec/1e6:0,o={bytes,runs,duration_seconds:+sec.toFixed(2),average_mbps:+mbps.toFixed(2),errors};D.sustained_download=o;kv('sustainedStats',o);$('sustainedResult').textContent='Completed bounded transfer. This measures the browser-to-Cloudflare route, not the local ISP link in isolation.';}
function assessment(){const notes=[];const q=D.same_origin_quality,b=D.bufferbloat,s=D.connection_stability,tls=D.server_tls,ip=D.ip_intelligence,net=D.network;
 if(!navigator.onLine)notes.push('Browser reports offline. Check Wi-Fi/Ethernet, router status and captive portal sign-in.');
 if(q){if(q.average_ms>250)notes.push('Same-origin average latency is high (>250 ms). Retest from another network and compare server location/hosting load.');if(q.mean_absolute_jitter_ms>40)notes.push('Same-origin timing varies substantially. Repeat the test; browser scheduling and server load can contribute.');}
 if(b&&typeof b.latency_increase_ms==='number'){if(b.latency_increase_ms>100)notes.push('Latency increased by more than 100 ms under load. Check router QoS/SQM, upload saturation and background transfers.');else if(b.latency_increase_ms>40)notes.push('Moderate loaded-latency increase detected. Retest when the connection is otherwise idle.');else notes.push('Loaded latency did not rise substantially in this sample. This is not a formal bufferbloat grade.');}
 if(tls){for(const [h,v] of Object.entries(tls)){if(v.ok&&typeof v.days_until_expiry==='number'&&v.days_until_expiry<30)notes.push('TLS certificate for '+h+' expires in under 30 days.');if(!v.ok)notes.push('TLS inspection for '+h+' failed or was blocked: '+(v.error||'unknown error')+'.');}}
 if(D.server_dns){for(const [h,v] of Object.entries(D.server_dns)){if(v.ok&&!v.records?.A?.length&&!v.records?.AAAA?.length)notes.push('No A/AAAA records were returned for '+h+' by the hosting resolver.');}}
 if(D.download?.mbps&&D.sustained_download?.average_mbps&&D.sustained_download.average_mbps<D.download.mbps*.5)notes.push('Sustained throughput was substantially below the short download sample; network variation, endpoint throttling or host load may explain this.');
 if(!notes.length)notes.push('No obvious issue was identified from the tests currently run. Run connection quality, bufferbloat, DNS, TLS and throughput checks for a more complete assessment.');
 notes.push('Interpret all results as diagnostic indicators. Browser tests do not replace router, operating-system or ISP-level diagnostics.');
 D.assessment={generated_at:new Date().toISOString(),findings:notes,tests_present:{same_origin_quality:!!q,bufferbloat:!!b,server_dns:!!D.server_dns,server_tls:!!tls,server_http:!!D.server_http,sustained_download:!!D.sustained_download}};$('assessmentResult').textContent=notes.map((n,i)=>(i+1)+'. '+n).join('\\n');}
const trouble={quality,buffer:bufferTest,sustained,assess:assessment,dns:()=>serverCheck('dns'),tls:()=>serverCheck('tls'),http:()=>serverCheck('http'),resources,frames,micstart:micStart,micstop:micStop,left:()=>channel('left'),right:()=>channel('right'),sweep:()=>playTone(true),reset:()=>{keyT={n:0,last:'—',codes:[]};ptrT={move:0,click:0,wheel:0,x:'—',y:'—'};inputRender();}};
document.querySelectorAll('[data-trouble]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await trouble[b.dataset.trouble]();}catch(e){console.error(e);if($('bResult'))$('bResult').textContent=e.message;}finally{b.disabled=false;}}));
