 function fingerprint(){const signals={user_agent:!!navigator.userAgent,platform:!!navigator.platform,languages:Array.isArray(navigator.languages)?navigator.languages.length:0,timezone:!!Intl.DateTimeFormat().resolvedOptions().timeZone,screen_dimensions:!!(screen.width&&screen.height),pixel_ratio:!!window.devicePixelRatio,hardware_concurrency:!!navigator.hardwareConcurrency,device_memory:!!navigator.deviceMemory,touch_points:!!navigator.maxTouchPoints,webgl:!!D.webgl?.supported,canvas_sample:!!D.canvas_hash,audio_sample:!!D.audio_hash,media_devices:!!navigator.mediaDevices,connection_api:!!navigator.connection,webdriver_signal:typeof navigator.webdriver==='boolean'};const count=Object.values(signals).filter(v=>v===true||(typeof v==='number'&&v>0)).length;const out={observable_signal_count:count,possible_signal_categories:Object.keys(signals).length,exposure_level:count>=12?'Higher signal exposure':count>=8?'Moderate signal exposure':'Lower signal exposure',signals,note:'This does not estimate uniqueness or identify you. Signals can change and may be intentionally reduced.'};D.fingerprint_exposure=out;safePut('fingerprintStats',{Exposure:out.exposure_level,Observable_signals:count,Categories:Object.keys(signals).length});$x('fingerprintResult').textContent=JSON.stringify(signals,null,2);}
