 const trackerPatterns=[/google-analytics/i,/googletagmanager/i,/doubleclick/i,/googlesyndication/i,/facebook\.net/i,/connect\.facebook/i,/hotjar/i,/segment\.io/i,/mixpanel/i,/amplitude/i,/clarity\.ms/i,/newrelic/i,/sentry/i];
