 $x('policyRun')?.addEventListener('click',async()=>{try{const response=await fetch(location.href,{method:'GET',cache:'no-store',credentials:'same-origin'});const names=['content-security-policy','strict-transport-security','x-content-type-options','x-frame-options','referrer-policy','permissions-policy','cross-origin-opener-policy','cross-origin-embedder-policy','cross-origin-resource-policy'];const h={};names.forEach(n=>h[n]=response.headers.get(n));const csp=h['content-security-policy']||'';const out={status:response.status,policies:h,csp_directives:{default_src:/default-src\s+([^;]+)/i.exec(csp)?.[1]||null,script_src:/script-src\s+([^;]+)/i.exec(csp)?.[1]||null,object_src:/object-src\s+([^;]+)/i.exec(csp)?.[1]||null,frame_ancestors:/frame-ancestors\s+([^;]+)/i.exec(csp)?.[1]||null},note:'Only headers exposed on this same-origin response are checked.'};D.response_policy_audit=out;safePut('policyStats',{CSP:!!h['content-security-policy'],HSTS:!!h['strict-transport-security'],X_Content_Type_Options:!!h['x-content-type-options'],X_Frame_Options:!!h['x-frame-options'],Referrer_Policy:!!h['referrer-policy'],Permissions_Policy:!!h['permissions-policy']});$x('policyResult').textContent=JSON.stringify(out,null,2);}catch(e){$x('policyResult').textContent='Audit failed: '+e.message;}});
 function runCpu(){const rounds=5,iterations=500000;const times=[];let checksum=0;for(let r=0;r<rounds;r++){const start=performance.now();let x=0;for(let i=1;i<=iterations;i++)x+=(i%97)*Math.sqrt(i);times.push(performance.now()-start);checksum+=x;}const sorted=[...times].sort((a,b)=>a-b);const out={rounds,iterations_per_round:iterations,median_ms:+sorted[2].toFixed(2),fastest_ms:+sorted[0].toFixed(2),slowest_ms:+sorted[4].toFixed(2),operations_per_second_estimate:Math.round(iterations/(sorted[2]/1000)),checksum:Math.round(checksum),note:'JavaScript main-thread microbenchmark; compare only under similar conditions'};D.cpu_benchmark=out;safePut('cpuBenchStats',out);$x('cpuBenchResult').textContent='Benchmark complete. Close other heavy tabs and repeat for a more stable comparison.';}
