 function idbRun(){return new Promise((resolve,reject)=>{if(!indexedDB)return reject(Error('IndexedDB unavailable'));const name='araha-devdiag-temp-'+Date.now(),req=indexedDB.open(name,1);req.onerror=()=>reject(req.error||Error('Database open failed'));req.onupgradeneeded=()=>req.result.createObjectStore('bench');req.onsuccess=()=>{const db=req.result,key='sample',value=new Uint8Array(1024*1024);const t0=performance.now(),tx=db.transaction('bench','readwrite');tx.objectStore('bench').put(value,key);tx.oncomplete=()=>{const write=performance.now()-t0,t1=performance.now(),readTx=db.transaction('bench','readonly'),get=readTx.objectStore('bench').get(key);get.onsuccess=()=>{const read=performance.now()-t1;db.close();const del=indexedDB.deleteDatabase(name);del.onsuccess=()=>resolve({payload_mb:1,write_ms:+write.toFixed(2),read_ms:+read.toFixed(2),bytes_read:get.result?.byteLength||0});del.onerror=()=>resolve({payload_mb:1,write_ms:+write.toFixed(2),read_ms:+read.toFixed(2),cleanup:'Database cleanup pending'});};get.onerror=()=>{db.close();reject(get.error||Error('Read failed'));};};tx.onerror=()=>{db.close();reject(tx.error||Error('Write failed'));};};});}
